<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { request } from '../api'
import { basisPointsFromInput } from '../domain.js'
const config=ref<Record<string,any>>({}),broker=ref('0'),member=ref('0'),days=ref('7'),loading=ref(true),busy=ref(false),error=ref(''),success=ref('')
const growth=ref<Record<string,number>>({}),growthNames:Record<string,string>={invitation_points:'邀请注册成长值',rental_points_per_day:'租赁每天成长值',lesson_points:'完成章节成长值',exam_points:'考试通过成长值',post_points:'发布内容成长值'}
async function load(){loading.value=true;error.value='';try{config.value=await request('/settings');const distribution=config.value.distribution||{};broker.value=String(Number(distribution.broker_bps||0)/100);member.value=String(Number(distribution.member_bps||0)/100);days.value=String(distribution.settlement_days??7);growth.value=Object.fromEntries(Object.keys(growthNames).map(key=>[key,Number(config.value.growth?.[key]||0)]))}catch(err){error.value=(err as Error).message}finally{loading.value=false}}
async function save(){busy.value=true;error.value='';success.value='';try{const broker_bps=basisPointsFromInput(broker.value),member_bps=basisPointsFromInput(member.value),settlement_days=Number(days.value);if(broker_bps+member_bps>10000)throw new Error('经纪人及会员合计比例不能超过 100%');if(!Number.isSafeInteger(settlement_days)||settlement_days<0||settlement_days>365)throw new Error('结算周期须为 0 至 365 天的整数');for(const [key,value] of Object.entries(growth.value))if(!Number.isSafeInteger(value)||value<0||value>10000)throw new Error(growthNames[key]+'须为0至10000的整数');await request('/settings',{method:'PUT',body:JSON.stringify({growth:growth.value,distribution:{broker_bps,member_bps,settlement_days}})});success.value='配置已保存。仅对服务端允许的新确认结算生效。';await load()}catch(err){error.value=(err as Error).message}finally{busy.value=false}}
onMounted(load)
</script>
<template>
  <div class="page-heading"><div><h1>分红与结算配置</h1><p>以平台逐单确认的可分配利润为基数，由服务端生成不可重复的财务账本。</p></div></div><p v-if="error" class="notice danger" role="alert">{{ error }}</p><p v-if="success" class="notice success" role="status">{{ success }}</p>
  <section class="panel settings-panel"><div class="panel-heading"><h2>分配比例</h2><span class="eyebrow">平台设置</span></div><div v-if="loading" class="empty">正在读取配置…</div><form v-else class="settings-form" @submit.prevent="save"><label><span>销售经纪人比例（%）</span><div class="input-suffix"><input v-model="broker" inputmode="decimal" required /><span>%</span></div><small>在订单利润确认时显式选定销售经纪人。</small></label><label><span>会员分红比例（%）</span><div class="input-suffix"><input v-model="member" inputmode="decimal" required /><span>%</span></div><small>仅向显式选定且满足服务端资格要求的会员分配。</small></label><label><span>结算周期（天）</span><div class="input-suffix"><input v-model="days" type="number" min="0" max="365" required /><span>天</span></div><small>退款成功会调整分红；部分退款后须重新确认剩余利润。</small></label><h3 class="section-heading">成长值任务规则</h3><label v-for="(name,key) in growthNames" :key="key"><span>{{ name }}</span><input v-model.number="growth[key]" type="number" min="0" max="10000" required /><small>0表示该任务不授予成长值，金额分红与成长值独立计算。</small></label><p class="notice">系统不会按订单总价、报价或定金直接计算分红。未确认利润的订单不能结算。</p><button class="button primary" :disabled="busy">{{ busy?'正在保存…':'保存配置' }}</button></form></section>
</template>
